def _key(version):
    core, _, pre = version.partition("-")
    numbers = tuple(int(part) for part in core.split("."))
    return numbers, (0, pre) if pre else (1, "")


def compare_versions(a, b):
    ka, kb = _key(a), _key(b)
    return (ka > kb) - (ka < kb)

