def wrap(text, width):
    lines = []
    current = ""
    for word in text.split():
        if not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current += " " + word
        else:
            lines.append(current)
            current = word
    if current:
        lines.append(current)
    return lines

import heapq


def shortest_path_cost(graph, start, goal):
    queue = [(0, start)]
    best = {start: 0}
    while queue:
        cost, node = heapq.heappop(queue)
        if node == goal:
            return cost
        if cost > best.get(node, float("inf")):
            continue
        for neighbour, weight in graph.get(node, {}).items():
            new_cost = cost + weight
            if new_cost < best.get(neighbour, float("inf")):
                best[neighbour] = new_cost
                heapq.heappush(queue, (new_cost, neighbour))
    return None

def parse_csv_line(line):
    fields, field = [], []
    i, quoted = 0, False
    while i < len(line):
        char = line[i]
        if quoted:
            if char == '"':
                if i + 1 < len(line) and line[i + 1] == '"':
                    field.append('"')
                    i += 1
                else:
                    quoted = False
            else:
                field.append(char)
        elif char == '"':
            quoted = True
        elif char == ",":
            fields.append("".join(field))
            field = []
        else:
            field.append(char)
        i += 1
    if quoted:
        raise ValueError("unterminated quote")
    fields.append("".join(field))
    return fields

import re

_SECRET = re.compile(r"(?i)\b(password|token|secret|api_key)=([^\s,;&]*)")


def redact(text):
    return _SECRET.sub(lambda m: f"{m.group(1)}=***", text)

_NUMERALS = [(1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"), (90, "XC"),
             (50, "L"), (40, "XL"), (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")]


def to_roman(number):
    if not 1 <= number <= 3999:
        raise ValueError("out of range")
    out = []
    for value, symbol in _NUMERALS:
        count, number = divmod(number, value)
        out.append(symbol * count)
    return "".join(out)

